<?php
declare(strict_types=1);
// Execute uma única vez após publicar a atualização. Exclua este arquivo depois.
$configFile=__DIR__.'/config.php';
if(!is_file($configFile)){http_response_code(503);exit('Configure config.php antes de atualizar.');}
$c=require $configFile;
try{
 $pdo=new PDO(sprintf('mysql:host=%s;dbname=%s;charset=utf8mb4',$c['db_host'],$c['db_name']),$c['db_user'],$c['db_pass'],[PDO::ATTR_ERRMODE=>PDO::ERRMODE_EXCEPTION]);
 $sql=[
 "CREATE TABLE IF NOT EXISTS property_members (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,property_id INT UNSIGNED NOT NULL,user_id INT UNSIGNED NOT NULL,permission ENUM('view','edit','manage') NOT NULL DEFAULT 'view',invited_by INT UNSIGNED NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,UNIQUE KEY uq_property_member(property_id,user_id),CONSTRAINT fk_pm_property FOREIGN KEY(property_id) REFERENCES properties(id) ON DELETE CASCADE,CONSTRAINT fk_pm_user FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE,CONSTRAINT fk_pm_inviter FOREIGN KEY(invited_by) REFERENCES users(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci",
 "CREATE TABLE IF NOT EXISTS visits (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,property_id INT UNSIGNED NOT NULL,field_id INT UNSIGNED NULL,professional_id INT UNSIGNED NOT NULL,visit_date DATE NOT NULL,status ENUM('scheduled','completed','cancelled') NOT NULL DEFAULT 'scheduled',summary TEXT NULL,next_steps TEXT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,CONSTRAINT fk_visits_property FOREIGN KEY(property_id) REFERENCES properties(id) ON DELETE CASCADE,CONSTRAINT fk_visits_field FOREIGN KEY(field_id) REFERENCES fields(id) ON DELETE SET NULL,CONSTRAINT fk_visits_user FOREIGN KEY(professional_id) REFERENCES users(id) ON DELETE CASCADE,INDEX idx_visits_professional(professional_id,visit_date)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci",
 "CREATE TABLE IF NOT EXISTS recommendations (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,property_id INT UNSIGNED NOT NULL,field_id INT UNSIGNED NULL,author_id INT UNSIGNED NOT NULL,title VARCHAR(180) NOT NULL,description TEXT NOT NULL,priority ENUM('low','medium','high') NOT NULL DEFAULT 'medium',status ENUM('open','accepted','done','cancelled') NOT NULL DEFAULT 'open',due_date DATE NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,CONSTRAINT fk_recommend_property FOREIGN KEY(property_id) REFERENCES properties(id) ON DELETE CASCADE,CONSTRAINT fk_recommend_field FOREIGN KEY(field_id) REFERENCES fields(id) ON DELETE SET NULL,CONSTRAINT fk_recommend_author FOREIGN KEY(author_id) REFERENCES users(id) ON DELETE CASCADE,INDEX idx_recommend_property(property_id,status)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci",
 "CREATE TABLE IF NOT EXISTS tasks (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,property_id INT UNSIGNED NOT NULL,field_id INT UNSIGNED NULL,created_by INT UNSIGNED NOT NULL,assigned_to INT UNSIGNED NULL,title VARCHAR(180) NOT NULL,description TEXT NULL,due_date DATE NULL,status ENUM('open','doing','done','cancelled') NOT NULL DEFAULT 'open',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,CONSTRAINT fk_tasks_property FOREIGN KEY(property_id) REFERENCES properties(id) ON DELETE CASCADE,CONSTRAINT fk_tasks_field FOREIGN KEY(field_id) REFERENCES fields(id) ON DELETE SET NULL,CONSTRAINT fk_tasks_creator FOREIGN KEY(created_by) REFERENCES users(id) ON DELETE CASCADE,CONSTRAINT fk_tasks_assignee FOREIGN KEY(assigned_to) REFERENCES users(id) ON DELETE SET NULL,INDEX idx_tasks_assignee(assigned_to,status)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci",
 "CREATE TABLE IF NOT EXISTS attachments (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,property_id INT UNSIGNED NOT NULL,uploaded_by INT UNSIGNED NOT NULL,original_name VARCHAR(255) NOT NULL,stored_name VARCHAR(255) NOT NULL,mime_type VARCHAR(120) NOT NULL,file_size INT UNSIGNED NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,CONSTRAINT fk_attach_property FOREIGN KEY(property_id) REFERENCES properties(id) ON DELETE CASCADE,CONSTRAINT fk_attach_user FOREIGN KEY(uploaded_by) REFERENCES users(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci"
 ];
 foreach($sql as $q)$pdo->exec($q);
 header('Content-Type:text/html;charset=utf-8');
 echo '<!doctype html><html lang="pt-BR"><meta charset="utf-8"><body style="font:16px system-ui;max-width:700px;margin:60px auto;padding:20px"><h1 style="color:#1f6b45">Atualização concluída</h1><p>Compartilhamento, visitas, recomendações, tarefas e anexos foram habilitados no banco.</p><strong>Exclua upgrade.php do servidor agora.</strong></body></html>';
}catch(Throwable $e){http_response_code(500);error_log('Agro upgrade: '.$e->getMessage());echo 'Não foi possível atualizar o banco. Consulte o log PHP.';}
